package msgpack

import (
	"reflect"
	"runtime"
	"testing"
)

// promoted reports whether method name on t is inherited from an embedded field. The compiler generates the
// promoted-method wrapper, and its source file is "<autogenerated>".
func promoted(t reflect.Type, name string) (isPromoted, ok bool) {
	m, ok := t.MethodByName(name)
	if !ok {
		return false, false
	}
	f := runtime.FuncForPC(m.Func.Pointer())
	file, _ := f.FileLine(f.Entry())
	return file == "<autogenerated>", true
}

var nativePairs = [][2]string{
	{"CalcAmountOut", "CalcAmtOut"},
	{"CalcAmountIn", "CalcAmtIn"},
	{"UpdateBalance", "UpdateState"},
	{"CalculateLimit", "CalcLimit"},
}

// staleInherited lists the legacy methods t declares whose native twin t inherits. Dispatch prefers the native
// method, so such a type would silently quote with the embedded parent's math. Shadow the native method on the
// embedder (reimplement it, or return an error).
func staleInherited(t reflect.Type) (stale []string) {
	for _, p := range nativePairs {
		legacyPromoted, hasLegacy := promoted(t, p[0])
		nativePromoted, hasNative := promoted(t, p[1])
		if hasLegacy && !legacyPromoted && hasNative && nativePromoted {
			stale = append(stale, p[0])
		}
	}
	return stale
}

func TestNoStaleInheritedNativeMethod(t *testing.T) {
	for _, v := range registeredTypes {
		if stale := staleInherited(reflect.TypeOf(v)); len(stale) > 0 {
			t.Errorf("%T declares %v but inherits the native twin", v, stale)
		}
	}
}

type fakeParent struct{}

func (*fakeParent) CalcAmountOut() {}
func (*fakeParent) CalcAmtOut()    {}

type fakeEmbedder struct{ *fakeParent }

func (*fakeEmbedder) CalcAmountOut() {}

// The check must flag the embedder that overrides only the legacy method, and not the parent.
func TestStaleInheritedDetectsEmbedder(t *testing.T) {
	if got := staleInherited(reflect.TypeOf(&fakeEmbedder{})); len(got) != 1 || got[0] != "CalcAmountOut" {
		t.Fatalf("embedder not flagged: %v", got)
	}
	if got := staleInherited(reflect.TypeOf(&fakeParent{})); len(got) != 0 {
		t.Fatalf("parent flagged: %v", got)
	}
}
